ps://web.archive.org/web/20140726065615im_/http://www.atpaddles.com/assets/images/paddles/samurai_glass_lrg.jpg","page_url":"https://web.archive.org/web/2/https://www.atpaddles.com/eu/en/paddles/samurai-glass","kind":"maker","credit":"AT","batch":"photos-1102"}]},{"category":"paddle","brand":"AT","model":"Titan","variant":"Sport series, straight","size":null,"images":[{"url":"https://web.archive.org/web/20140726134322im_/http://www.atpaddles.com/assets/images/paddles/titan_lrg.jpg","page_url":"https://web.archive.org/web/2/https://www.atpaddles.com/eu/en/paddles/titan","kind":"maker","credit":"AT","batch":"photos-1102"}]},{"category":"paddle","brand":"AT","model":"Titan","variant":"Sport series, bent","size":null,"images":[{"url":"https://web.archive.org/web/20140726134322im_/http://www.atpaddles.com/assets/images/paddles/titan_lrg.jpg","page_url":"https://web.archive.org/web/2/https://www.atpaddles.com/eu/en/paddles/titan","kind":"maker","credit":"AT","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Double Diamond","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://wernerpaddles.com/cdn/shop/products/DoubleDiamond_Blade.jpg?v=1538164992","page_url":"https://wernerpaddles.com/products/werner-double-diamond-1-piece-bent-shaft-kayak-paddle","kind":"maker","credit":"Werner","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Player Carbon","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://web.archive.org/web/20130503002935im_/http://www.wernerpaddles.com/images/paddles/whitewater/performance/page/Player_Carbon.jpg","page_url":"https://web.archive.org/web/2013/http://www.wernerpaddles.com/paddles/buy_now/index.php?paddle_ID=21&discipline=Whitewater&line=Performance&paddle_name=Player+Carbon","kind":"maker","credit":"Werner","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Side Kick","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://web.archive.org/web/20130507073151im_/http://www.wernerpaddles.com/images/paddles/whitewater/premium/page/Side_Kick.jpg","page_url":"https://web.archive.org/web/2013/http://www.wernerpaddles.com/paddles/buy_now/index.php?paddle_ID=24&discipline=Whitewater&line=Premium&paddle_name=Side+Kick","kind":"maker","credit":"Werner","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Side Kick","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://web.archive.org/web/20130507073151im_/http://www.wernerpaddles.com/images/paddles/whitewater/premium/page/Side_Kick.jpg","page_url":"https://web.archive.org/web/2013/http://www.wernerpaddles.com/paddles/buy_now/index.php?paddle_ID=24&discipline=Whitewater&line=Premium&paddle_name=Side+Kick","kind":"maker","credit":"Werner","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://web.archive.org/web/20130507111204im_/http://www.wernerpaddles.com/images/paddles/whitewater/premium/page/Twist.jpg","page_url":"https://web.archive.org/web/2013/http://www.wernerpaddles.com/paddles/buy_now/index.php?paddle_ID=29&discipline=Whitewater&line=Premium&paddle_name=Twist","kind":"maker","credit":"Werner","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://web.archive.org/web/20130507111204im_/http://www.wernerpaddles.com/images/paddles/whitewater/premium/page/Twist.jpg","page_url":"https://web.archive.org/web/2013/http://www.wernerpaddles.com/paddles/buy_now/index.php?paddle_ID=29&discipline=Whitewater&line=Premium&paddle_name=Twist","kind":"maker","credit":"Werner","batch":"photos-1102"}]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"4 piece, straight shaft","size":null,"images":[{"url":"https://web.archive.org/web/20130507111204im_/http://www.wernerpaddles.com/images/paddles/whitewater/premium/page/Twist.jpg","page_url":"https://web.archive.org/web/2013/http://www.wernerpaddles.com/paddles/buy_now/index.php?paddle_ID=29&discipline=Whitewater&line=Premium&paddle_name=Twist","kind":"maker","credit":"Werner","batch":"photos-1102"}]}]$seed$::jsonb) AS s(
        category material_category, brand text, model text, variant text, size text,
        images jsonb
    )
), target AS (
    SELECT m.id AS material_id, s.images
    FROM seed s
    JOIN materials m ON m.category = s.category
        AND lower(btrim(m.brand)) = lower(btrim(s.brand))
        AND lower(btrim(m.model)) = lower(btrim(s.model))
        AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(s.variant, '')))
        AND lower(btrim(COALESCE(m.size, ''))) = lower(btrim(COALESCE(s.size, '')))
        AND m.created_by = 'system-catalogue'
    WHERE NOT EXISTS (
        SELECT 1 FROM materials o
        JOIN material_images oi ON oi.material_id = o.id
            AND oi.source_kind <> 'user' AND oi.status <> 'removed'
        WHERE o.category = m.category
          AND lower(btrim(o.brand)) = lower(btrim(m.brand))
          AND lower(btrim(o.model)) = lower(btrim(m.model))
          AND lower(btrim(COALESCE(o.variant, ''))) = lower(btrim(COALESCE(m.variant, '')))
    )
)
INSERT INTO material_images (material_id, source_url, host, page_url, credit, source_kind)
SELECT t.material_id, i->>'url', lower(substring(i->>'url' from '^https://([^/?#:@]+)')),
       i->>'page_url', i->>'credit', i->>'kind'
FROM target t
CROSS JOIN LATERAL jsonb_array_elements(t.images) AS i
ON CONFLICT (material_id, source_url) DO NOTHING;
